import{_ as o,C as t,o as r,c as i,a6 as e,E as s}from"./chunks/framework.B_q3ZJNF.js";const _=JSON.parse('{"title":"均线与趋势：技术分析能信几分","description":"","frontmatter":{"title":"均线与趋势：技术分析能信几分"},"headers":[],"relativePath":"astock-course/05-trend-ma.md","filePath":"astock-course/docs/05-trend-ma.md"}'),n={name:"astock-course/05-trend-ma.md"};function p(d,a,h,D,c,u){const l=t("MaCrossChart");return r(),i("div",null,[a[0]||(a[0]=e('<h1 id="均线与趋势-技术分析能信几分" tabindex="-1">均线与趋势：技术分析能信几分 <a class="header-anchor" href="#均线与趋势-技术分析能信几分" aria-label="Permalink to &quot;均线与趋势：技术分析能信几分&quot;">​</a></h1><p>设想一个足够勤快的你：每天收盘后花五分钟，看一眼图形上的两条均线（把最近若干天的收盘价求平均连成的线，下文就教它），线给出买入信号就买，给出卖出信号就卖，坚持许多年，一次不落。这套动作在坊间有固定的口诀，叫「金叉买入、死叉卖出」。听上去无懈可击：不猜底、不追高，信号出现才动手。可长期回测（拿固定规则在一段行情上逐日重演、期末对账）反复交出同一个尴尬的结局——把手续费一笔一笔扣掉，这套勤快的动作，常常跑不赢一个开完户就睡大觉、闭眼拿着不动的人。这不是玄学，是一笔可以逐笔对账的账：多出来的每一次动作都要付佣金、过户费，卖出还要缴印花税，而信号本身还有迟到的毛病。本章不引用任何来历不明的十年实盘数字，而是当场生成一段 250 个交易日的合成行情（教学示意，与任何真实个股无关），给「金叉买、死叉卖」和「拿着不动」各发一万元，让它们买同一只股票、同场跑完，期末对账。看完这笔账，「技术分析能信几分」就有了一个带数字的答案。</p><h2 id="工具箱" tabindex="-1">工具箱 <a class="header-anchor" href="#工具箱" aria-label="Permalink to &quot;工具箱&quot;">​</a></h2><p>本章调用八块旧积木，分两组。读行情的三条：K线——用实体与影线记下一个周期的开盘、收盘、最高、最低四个价格，均线要用的收盘价就印在每根蜡烛上（第 4 章）；阳线与阴线——收盘高于开盘为阳线、低于为阴线，只描述当天谁赢，不预测明天（第 4 章）；成交量——一个周期内成交的股数，价格运动的燃料（第 4 章）。算账的五条：收益率——（期末 − 期初）÷ 期初，判断输赢的尺子（第 1 章）；复利——收益并入本金再生收益，小差距长期按指数放大（第 1 章）；佣金——成交金额乘费率、买卖双向，课程示例为万 2.5、单笔最低 5 元（第 3 章）；过户费——成交金额乘万 0.1、买卖双向（第 3 章）；印花税——只在卖出时按成交金额收万 5（第 3 章）。手边有这八条，本章的每一笔账都能落到纸面。</p><h2 id="原理-一条线怎么从蜡烛里长出来" tabindex="-1">原理：一条线怎么从蜡烛里长出来 <a class="header-anchor" href="#原理-一条线怎么从蜡烛里长出来" aria-label="Permalink to &quot;原理：一条线怎么从蜡烛里长出来&quot;">​</a></h2><h3 id="均线-把二十天合成一个数" tabindex="-1">均线：把二十天合成一个数 <a class="header-anchor" href="#均线-把二十天合成一个数" aria-label="Permalink to &quot;均线：把二十天合成一个数&quot;">​</a></h3><p>均线——把最近 N 个收盘价加起来除以 N，再把每天得到的平均数连成曲线，记作 MA(N)。它不是凭空发明的新指标，是你手里的 K 线直接组装出来的：只取每根蜡烛的收盘价这一格，求平均，别的什么都不加。</p><p>它凭什么有资格概括行情？给一个近似：每天的成交都发生在当时的价格附近，最近 20 天收盘价的平均，差不多是这 20 天里进场那批人的平均持仓成本。成本是持仓者心里那杆秤的零点——价格在成本上方，多数人拿得从容；跌破成本，多数人开始难受。均线因此成了速读「全场平均是赚是亏」的捷径。也正因为只取收盘价，它是粗略近似：真实的筹码分布还要按成交量加权，本章先取最简口径。</p><p>先亲手算一遍（纸笔即可，数字取自导出文件 docs/assets/data/ma-cross.json）。D246 到 D250 五天的收盘价是 18.68、18.76、18.54、18.67、18.79。合计 93.44，除以 5 得 18.69——这就是 D250 的 MA5，与本章图表上悬停读出的数一分不差。</p><p>均线的性格藏在「平均」两个字里。一根大阳线再猛，摊进 MA20 也只占二十分之一的权重：新信息要一天天渗进平均数，均线只能慢半拍地挪动。这决定了它的身份，<strong>均线是确认工具，不是预警工具</strong>——等你看到它转向，行情早已走出一段。</p><h3 id="趋势-高低点在说方向" tabindex="-1">趋势：高低点在说方向 <a class="header-anchor" href="#趋势-高低点在说方向" aria-label="Permalink to &quot;趋势：高低点在说方向&quot;">​</a></h3><p>趋势——价格运动的方向性：高点与低点同时抬升叫上升趋势，同时下移叫下降趋势，反复交织叫震荡。成因不难推：买方的力量只要在一段时间里持续压过卖方，每次回调总有人抢着接、每次冲高总能创新高，价格就走台阶；反过来走下台阶；两边势均力敌，就来回织布。</p><p>判断它不靠任何指标，用剧情就能练。这段 250 天的行情里，三个回调低点一个比一个高——D19 的 9.53、D79 的 10.25、D166 的 12.69；三个高点也一个比一个高——D56 的 11.15、D132 的 14.45、D250 的 18.79。高低点同时抬升，这是教科书式的上升趋势；中间夹着 D101 到 D180 的震荡段，价格在 12.7 到 14.5 之间来回，属于交织状态。</p><p>均线在这里的身份是状态速读器：价格站在向上翘的 MA20 上方，当下大概率处在上升趋势；跌下去、均线走平拐头，状态就要重新判。<strong>趋势会延续，也会结束，只跟随、不信仰</strong>——它描述的是现在，不保证明天。</p><h3 id="支撑与压力-区域-不是铁轨" tabindex="-1">支撑与压力：区域，不是铁轨 <a class="header-anchor" href="#支撑与压力-区域-不是铁轨" aria-label="Permalink to &quot;支撑与压力：区域，不是铁轨&quot;">​</a></h3><p>支撑与压力——价格容易止跌的区域（支撑）与容易受阻的区域（压力）。它们多来自前期密集成交留下的记忆：每一笔成交都是一次股权换手（第 2 章），套牢的筹码背后是一个个等回本就卖的持有人，踏空的一方则在旧价位等回踩就买。买卖单在旧成交密集的一带越堆越厚，价格走到这里就容易停住。反过来想就明白它为什么存在：要是某个价位没有任何成交记忆，价格没有理由偏偏在那里站住。</p><p>本剧情给出了标准样本。震荡段把一个箱体砸得很实：上沿一带，D119 收 13.94、D132 收 14.45，两次冲上去都被压回来。D132 那天盘中摸到 15.49，收出一根 1.04 元的上影线（第 4 章的读法：到达过，没守住）——压力在哪，影线先画了出来。下沿一带，D115 收 13.08、D155 收 13.07、D166 收 12.69，三次回踩全被接住；D115 那回踩时量能只有平日（中位数约 8.5 万手）的 0.78 倍，卖方越砸越轻。</p><p>但请盯紧措辞：是区域，不是铁轨。支撑 12.69 到 13.08 本身就是一条 3% 宽的地带，三次回踩的落点各不相同；你要是在 13.08 挂单等接回，就得受得住价格磨到 12.69 那 3% 的浮亏。把线当铁轨的人，会在 D132 看到「突破」就追，又在回落里割肉。还有一条规矩要记：一旦价格跌破支撑，同一条线常会翻转成反弹时的压力——本剧情没演到这一幕，留给你在真实行情里核对。D199 收 14.54，第一次收在箱体上沿之上，此后一路走到 18.79，再没回来考验这个区域。</p><h3 id="金叉与死叉-迟到的确认" tabindex="-1">金叉与死叉：迟到的确认 <a class="header-anchor" href="#金叉与死叉-迟到的确认" aria-label="Permalink to &quot;金叉与死叉：迟到的确认&quot;">​</a></h3><p>金叉与死叉——短期均线上穿长期均线为金叉，下穿为死叉，本章用 MA5 对 MA20。它被当成信号说得通：MA5 站上 MA20，意味着最近 5 天进场的平均成本已抬到 20 天平均成本之上，新钱愿意出更高的价钱，这常被读作趋势转强的确认；死叉反之。</p><p>但别忘了均线的性格：平均带来确认，也带来迟到。D73 死叉确认时，价格已从高点回落 4.04%；D79 收出本轮急跌的最低收盘 10.25，金叉却拖到 D85 才确认，当天收盘 11.19，已比最低点高出 9.17%，次日 D86 开盘 11.17 才轮到你动手。信号确认之时，行情早已换场——这就是把金叉当买入按钮的人付的隐形账单：每一次确认，都把最低价到确认价之间的一段让给了别人。</p><p>至此可以写下本章新能力的组装式：</p><blockquote><p><strong>回测 = 均线（第 4 章的收盘价求平均）＋ 交叉检测（新规则）＋ 五笔成本（第 3 章）＋ 收益率对账（第 1 章）</strong></p></blockquote><p>四样里三样是旧积木，新的只有「上穿买、下穿卖」这一条纪律。接下来的演练，就让这条纪律和「什么都不做」各带一万元，同场对账。</p><h2 id="演练-让两种纪律同场跑一年" tabindex="-1">演练：让两种纪律同场跑一年 <a class="header-anchor" href="#演练-让两种纪律同场跑一年" aria-label="Permalink to &quot;演练：让两种纪律同场跑一年&quot;">​</a></h2><p>先交代行情来路：D1 到 D250 共 250 个交易日，由课程组件按固定种子合成（教学示意，与任何真实个股无关），全部价格满足主板 ±10% 涨跌停板约束。想在本地复现，在课程根目录运行 <code>pnpm export</code>，数据文件 docs/assets/data/ma-cross.json 就会重新生成——连跑两次，逐字节一致。</p>',26)),s(l),a[1]||(a[1]=e('<p>图分上下两层。上层是 250 天的收盘价连线，叠着 MA5（黄）与 MA20（蓝），红三角是金叉、绿三角是死叉，全剧共 8 个：金叉 5 个、死叉 3 个。下层是两条净值曲线（净值 = 当天账户里的现金加持仓市值）：策略净值按纪律进出，持有净值在 D1 开盘以 9.98 元买入 1000 股后一股不卖。悬停任何一天，卡片给出收盘、两条均线和两条净值；信号日的卡片还会注明执行情况。</p><p>成交规则照现实来：信号收盘后才确认，出手最早在次一交易日，成交价用次日开盘价——开盘价由集合竞价产生（第 3 章）；每笔买入最早次日才能卖（T+1，第 3 章）；买卖双边付佣金与过户费，卖出另缴印花税（第 3 章），逐笔记账。持有不动只花一笔开仓的钱。</p><p>现在跟着剧情走一遍策略的账：</p><ul><li>D19 探出年内最低收盘 9.53。此时 MA5 还压在 MA20 下方，策略空仓干等，下跌段一股没拿。</li><li>D30 金叉确认，次日 D31 开盘 9.69 买入 1000 股——比持有不动的成本 9.98 还便宜 0.29 元，起步领先。</li><li>D73 死叉确认，D74 开盘 10.68 卖出：第一段趋势吃到手，这一回合净赚 974.45 元。信号不是没用。</li><li>可 D74 冲高回落、收出一根长上影的阳线，量能却放大到平日的 1.7 倍；随后几天价格一路阴跌，磨到 D79 才收出 10.25 的低点；随后急涨，金叉拖到 D85 才确认，当天收盘已比低点高出 9.17%。次日 D86 开盘 11.17 买回，每股倒贴 0.49 元；更难受的是，手头的钱只买得回 900 股——同样的车票，涨价了。</li><li>震荡段绞肉机开动：D115 卖 13.32、D123 买回 13.80，又倒贴 0.48 元；D139 卖 13.96、D175 买回 13.15，这一趟倒是赢了 0.81 元——信号有对的时候。</li><li>D181 之后行情突破上行，策略拿着 D175 买回的 900 股吃满从 13.15 到 18.79 的主升段。期末对账：策略 18,091.59 元，收益率 80.92%；持有不动 18,804.90 元，收益率 88.05%。</li></ul><h2 id="验证-先猜-再对账" tabindex="-1">验证：先猜，再对账 <a class="header-anchor" href="#验证-先猜-再对账" aria-label="Permalink to &quot;验证：先猜，再对账&quot;">​</a></h2><p>清单里的每个数字都能在图上与导出文件里逐分核对（docs/assets/data/ma-cross.json）。</p><ul><li>[ ] 找到全剧最近的一次死叉与最近的一次金叉，悬停读卡片。D138 应显示「死叉（MA5 下穿 MA20）：次日 D139 开盘 13.96 元执行」；D174 应显示「金叉（MA5 上穿 MA20）：次日 D175 开盘 13.15 元执行」。再用一句话说出各自含义：死叉是短期均线跌到长期均线下方、趋势转弱的滞后确认；金叉反之。</li><li>[ ] 先猜后跑：全剧图上共有几个三角标记？落纸写一个区间（三选一：5 个以内 / 6 到 8 个 / 9 个以上），再数图中标记并与 crosses 数组核对——应为 8 个（金叉 5、死叉 3），其中 D32 的金叉因当时已持仓而未执行。</li><li>[ ] 再猜一个：策略与持有的期末差距占总本金的比例，二选一——不足 1%，还是 1% 以上？对照图下对账条，应看到差距 713.31 元、占本金 7.13%，落在 1% 以上那一档。</li><li>[ ] 纸笔演算：悬停读出 D246 到 D250 五天的收盘价，列竖式求平均，再对照当天图上的 MA5 读数——应为 93.44 ÷ 5 ≈ 18.69，一分不差。</li><li>[ ] 定向破坏：把「死叉次日开盘卖出」这条规则整个拆掉，只买不卖。先落纸预言期末排名会不会反转，再按导出数据手算核对。拆掉后策略只剩 D31 一笔买入（9.69 元、1000 股），此后所有金叉因已持仓而作废。期末净值应得到：剩余现金 304.90 + 1000 × 18.79 = 19,094.90 元——反超持有不动的 18,804.90 元，排到第一。把卖出规则装回去，对账条应回到 18,091.59 元，图上一根蜡烛都不用动。</li></ul><p>破坏点选在「卖」上，因为它暴露了本章最反直觉的事实：在这段剧情里，把所有死叉卖出拆掉，期末反而更高——三次卖出里只有 D139 那趟赢回 0.81 元/股，其余都在帮倒忙。它守的是什么？卖出规则想守的是「躲开大跌」，可在迟到的确认下，它多数时候只是把筹码卖在半山腰，再由更迟的金叉高价接回。也别把结论推过头：这不是「永远不该卖」，而是卖出的代价与好处要靠回测算，不能靠信仰定。<strong>单看每一笔都像深思熟虑，合起来未必赢过什么都不做</strong>。</p><h2 id="收束-勤快的账单" tabindex="-1">收束：勤快的账单 <a class="header-anchor" href="#收束-勤快的账单" aria-label="Permalink to &quot;收束：勤快的账单&quot;">​</a></h2><p>开篇那位勤快的你，账现在能算了。250 个交易日，金叉买、死叉卖，一次没落下，期末 18,091.59 元；睡大觉的对手 18,804.90 元。差距 713.31 元来自两层。大头是滞后：确认永远慢半拍，震荡里一轮轮「卖在半山腰、买回在高处」，D86 那趟每股倒贴 0.49 元，D123 那趟 0.48 元。小头才是手续费：53.41 元，只占缺口的 7.5%——就算全免，策略也只追回到 18,145.00 元，照样落后。<strong>手续费是看得见的账单，滞后是看不见的那张，后者更贵</strong>。</p><p>技术分析的边界也就此清楚。均线、趋势、支撑与压力、金叉与死叉，四块新积木都在描述已经发生的行情：均线速读状态（MA(N) = 近 N 日收盘价之和 ÷ N），趋势看高低点，支撑压力是区域不是铁轨，金叉死叉是迟到的确认器。它们回答「现在是什么样子」，不回答「明天会怎样」——把描述工具当预测水晶球，正是开篇那 713.31 元的来历。也别滑向另一头说它们没用：判断一只股票当下的状态，这是通用语言；至于公司本身值不值，要换市值、盈利与估值那套秤来称（第 2 章），那是称重的功课（第 6 章）。</p><p>把 713.31 元的来历再拆一遍，就有两句要带走的提醒：金叉不是买入按钮——照它机械操作一整段行情，比不动少赚 713.31 元；跌到均线也不会自动反弹——D73 跌破 MA20 后，几个交易日又跌了 4.2%。还有一句别忘了：80.92% 是名义收益率，要跑赢通货膨胀才谈得上实际购买力（第 1 章）；好在本章对账用的是期末同一天的钱，连货币时间价值的折算都省了。四块积木的完整定义在附录「术语表」，回测的参数与简化口径（MA5 对 MA20、课程示例费率、次日开盘成交、期末按收盘估值）登记在附录「简化与差异清单」。</p><h3 id="自查-换一段行情-还会判断吗" tabindex="-1">自查：换一段行情，还会判断吗 <a class="header-anchor" href="#自查-换一段行情-还会判断吗" aria-label="Permalink to &quot;自查：换一段行情，还会判断吗&quot;">​</a></h3><ol><li>某只股票连续五天的收盘价是 12.40、12.36、12.51、12.47、12.61。手算这天的 MA5；若次日收 12.20，新的 MA5 变成多少？一天的大跌把五日均线拉低了多少？</li><li>一段行情的高点依次是 15.80、16.20、15.90，低点依次是 14.20、14.60、13.95。按定义判断：它还是上升趋势吗？卡在哪一条上？</li><li>某价格带 10.00 到 10.20 三次承接住回调，后来被放量跌破到 9.60。现在价格反弹到 10.10，这个旧支撑区此刻更像支撑还是压力？依据是什么？</li><li>把 MA5 对 MA20 换成 MA60 对 MA120：金叉死叉的确认会变早还是变晚？信号次数变多还是变少？付出的手续费合计会怎么变？</li><li>另一段剧情里，持有不动期末只剩 9500 元，交叉策略含费期末 9800 元。这能推翻本章的结论吗？为什么？</li></ol><details><summary>自查答案</summary><ol><li>当天 MA5 =（12.40 + 12.36 + 12.51 + 12.47 + 12.61）÷ 5 = 62.35 ÷ 5 = 12.47。次日把 12.40 挤出窗口、放进 12.20：新 MA5 =（12.36 + 12.51 + 12.47 + 12.61 + 12.20）÷ 5 = 62.15 ÷ 5 = 12.43。跌 0.41 元的收盘价只把均线拉低 0.04 元——单日在五日均值里只占五分之一权重，这就是「平均稀释新信息」的手感。</li><li>不再是。低点 14.60 到 13.95 已经下移，高点 16.20 到 15.90 也不再抬升——「高低点同时抬升」两条同时失守。按定义这至少要降级为「趋势存疑」，等待跌破前低后的走向再判。</li><li>更像压力。原来的支撑被跌破后，区域内被套的筹码等到解套就倾向于卖出，反弹到 10.00 到 10.20 一带会撞上这些抛单。跌破的支撑翻转成压力，这正是「区域不是铁轨」的另一面：同一个区域的身份，随多空结果切换。</li><li>确认更晚：长期均线要更多天的平均才会转身，拐点来得更迟。信号更少：长窗口抹平了小波动，假交叉次数下降。手续费合计更省：交易次数少了，费用笔数随之减少；但单次确认错过的行情段落更长——快线换慢线，是用更大的迟到换更少的折腾。</li><li>不能直接推翻。本章的结论不是「交叉策略永远更差」，而是「滞后的确认与交易成本在震荡里持续抽水」。在那段剧情里持有方亏 5%，说明行情整体下行，死叉把策略挡在部分下跌之外是可能的——具体输赢取决于行情形态。要知道一个规则的真实成色，办法与本章相同：固定规则、固定口径，跑足够长的行情再对账，而不是拿单段结果站队。</li></ol></details><p>行情与回测全部为教学示意·课程自产合成数据，与任何真实个股无关，不构成任何投资建议。</p>',16))])}const m=o(n,[["render",p]]);export{_ as __pageData,m as default};
